export type WuiIconType = keyof typeof WUI_ICONS;

export type WuiIconSize = 'xs' | 's' | 'm' | 'l' | 'xl';

const SIZE_PX: Record<WuiIconSize, number> = {
  xs: 12,
  s: 14,
  m: 16,
  l: 24,
  xl: 32,
};

export function WuiIcon({
  type,
  size = 'm',
  className = '',
  title,
}: {
  type: WuiIconType;
  size?: WuiIconSize | number;
  className?: string;
  title?: string;
}) {
  const def = WUI_ICONS[type];
  const px = typeof size === 'number' ? size : SIZE_PX[size];
  // Note: SVG strings below come verbatim from official @opensearch-project/oui & wazuh-dashboard-plugins assets.
  return (
    <svg
      width={px}
      height={px}
      viewBox={def.viewBox}
      fill="currentColor"
      aria-hidden={title ? undefined : true}
      role={title ? 'img' : undefined}
      aria-label={title}
      className={`ouiIcon ${def.isApp ? 'ouiIcon--app' : ''} shrink-0 inline-block align-middle ${className}`}
      dangerouslySetInnerHTML={{ __html: def.markup }}
    />
  );
}
